//! Metal shared wrap of a GGUF mmap. CPU-only hosts skip this module's wrap.

#[cfg(target_os = "macos")]
mod macos {
    use metal::{Device, MTLResourceOptions};

    pub struct MetalShared {
        _device: Device,
        _buffer: metal::Buffer,
        pub length: u64,
    }

    pub fn wrap_shared(bytes: &[u8]) -> Result<MetalShared, String> {
        let device = Device::system_default().ok_or_else(|| {
            String::from("no Metal device")
        })?;
        let ptr = bytes.as_ptr() as *const std::ffi::c_void;
        let length = bytes.len() as u64;
        if length == 0 {
            return Err(String::from("empty mapping"));
        }
        let buffer = device.new_buffer_with_bytes_no_copy(
            ptr,
            length,
            MTLResourceOptions::StorageModeShared,
            None,
        );
        Ok(MetalShared {
            _device: device,
            _buffer: buffer,
            length,
        })
    }
}

#[cfg(target_os = "macos")]
pub use macos::{wrap_shared, MetalShared};

#[cfg(not(target_os = "macos"))]
pub struct MetalShared {
    pub length: u64,
}

#[cfg(not(target_os = "macos"))]
pub fn wrap_shared(_bytes: &[u8]) -> Result<MetalShared, String> {
    Err(String::from("Metal is not compiled on this target"))
}

pub fn metal_compiled() -> bool {
    cfg!(target_os = "macos")
}

