        fn dlsym(handle: *mut c_void, symbol: *const i8) -> *mut c_void;
        fn sel_registerName(name: *const i8) -> *const c_void;
        fn objc_retain(obj: *mut c_void) -> *mut c_void;
        fn objc_release(obj: *mut c_void);
    }

    // aarch64 objc_msgSend: stret/fpret variants are not used for these calls.
    extern "C" {
        fn objc_msgSend();
    }

    type CreateDevice = unsafe extern "C" fn() -> *mut c_void;
    type MsgSendBuf = unsafe extern "C" fn(
        obj: *mut c_void,
        sel: *const c_void,
        bytes: *const c_void,
        length: usize,
        options: usize,
        deallocator: *mut c_void,
    ) -> *mut c_void;

    static METAL: OnceLock<Option<MetalFns>> = OnceLock::new();

    struct MetalFns {
        create_device: CreateDevice,
        new_buffer: MsgSendBuf,
        sel_new_buffer: *const c_void,
    }

    // Function pointers from dlopen stay valid for the process lifetime.
    unsafe impl Send for MetalFns {}
    unsafe impl Sync for MetalFns {}

    fn load() -> Option<&'static MetalFns> {
