#[derive(Debug, Clone, PartialEq, Eq)]
struct ReleaseVersion {
    major: u64,
    minor: u64,
    patch: u64,
    pre: Vec<PreIdent>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum PreIdent {
    Num(u64),
    Str(String),
}

impl PartialOrd for PreIdent {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for PreIdent {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        match (self, other) {
            (Self::Num(a), Self::Num(b)) => a.cmp(b),
            (Self::Num(_), Self::Str(_)) => std::cmp::Ordering::Less,
            (Self::Str(_), Self::Num(_)) => std::cmp::Ordering::Greater,
            (Self::Str(a), Self::Str(b)) => a.cmp(b),
        }
    }
}

fn parse_release_version(value: &str) -> Option<ReleaseVersion> {
    if !valid_version(value) {
        return None;
    }
    let (core, suffix) = match value.split_once('-') {
        Some((core, suffix)) => (core, Some(suffix)),
        None => (value, None),
    };
    let mut parts = core.split('.');
    let major = parts.next()?.parse().ok()?;
    let minor = parts.next()?.parse().ok()?;
    let patch = parts.next()?.parse().ok()?;
    let pre = match suffix {
        None => Vec::new(),
        Some(suffix) => suffix
            .split('.')
            .map(|ident| {
                if !ident.is_empty() && ident.bytes().all(|byte| byte.is_ascii_digit()) {
                    PreIdent::Num(ident.parse().unwrap_or(0))
                } else {
                    PreIdent::Str(ident.to_string())
                }
            })
            .collect(),
    };
    Some(ReleaseVersion {
        major,
        minor,
        patch,
        pre,
    })
}

/// Semver-style order for `X.Y.Z` and `X.Y.Z-suffix` names this CLI publishes.
///
/// A prerelease of a newer core (for example `0.2.0-rc.13`) is greater than
/// an older stable (`0.1.1`). A prerelease is less than the stable of the
/// same core (`0.2.0-rc.13` < `0.2.0`).
pub fn cmp_release_version(left: &str, right: &str) -> Option<std::cmp::Ordering> {
    let left = parse_release_version(left)?;
    let right = parse_release_version(right)?;
    match (
        left.major.cmp(&right.major),
        left.minor.cmp(&right.minor),
        left.patch.cmp(&right.patch),
    ) {
        (std::cmp::Ordering::Equal, std::cmp::Ordering::Equal, std::cmp::Ordering::Equal) => {}
        (major, _, _) if major != std::cmp::Ordering::Equal => return Some(major),
        (_, minor, _) if minor != std::cmp::Ordering::Equal => return Some(minor),
        (_, _, patch) => return Some(patch),
    }
    match (left.pre.is_empty(), right.pre.is_empty()) {
        (true, true) => Some(std::cmp::Ordering::Equal),
        (true, false) => Some(std::cmp::Ordering::Greater),
        (false, true) => Some(std::cmp::Ordering::Less),
        (false, false) => Some(left.pre.cmp(&right.pre)),
    }
}

