fn output(ui: &mut CoderUi, text: &str) {
    ui.entries.push(Entry::new(Role::Output, text));
    ui.scroll_override = None;
}

fn run_load_command(ui: &mut CoderUi, arguments: &[String]) {
    let Some(path) = arguments.first() else {
        output(ui, "Use `/load <path-to-gguf>`.");
        return;
    };
    let path = Path::new(path);
    if !path.is_file() {
        output(
            ui,
            &format!("GGUF not found at {}.", path.display()),
        );
        return;
    }
    let last = std::sync::Mutex::new((String::new(), false));
    let last = std::sync::Arc::new(last);
    let on_step = {
        let last = last.clone();
        std::sync::Arc::new(move |id: &str, message: &str, state: &str| {
            if let Ok(mut slot) = last.lock() {
                slot.0 = message.to_string();
                slot.1 = state == "fail";
            }
            let _ = (id, state);
        }) as std::sync::Arc<dyn Fn(&str, &str, &str) + Send + Sync>
    };
    let result = crate::inference::load_gguf_with_steps(
        path.to_path_buf(),
        false,
        true,
        Some(on_step),
    );
    let (message, fail) = last
        .lock()
        .map(|slot| slot.clone())
        .unwrap_or_else(|_| (String::new(), true));
    match result {
        Ok(()) => {
            ui.load_line = Some(if message.is_empty() {
                "Weights ready".to_string()
            } else {
                message
            });
            ui.memory_line = crate::inference::memory_status_line();
            ui.loading = false;
            ui.waiting = None;
        }
        Err(_) => {
            let fail_message = if message.is_empty() {
                "Not a GGUF file (magic is XXXX)".to_string()
            } else {
                message
            };
            ui.load_line = Some(fail_message.clone());
            ui.memory_line = None;
            ui.loading = false;
            ui.waiting = None;
            if fail || true {
                output(ui, &fail_message);
            }
        }
    }
}

fn run_unload_command(ui: &mut CoderUi) {
    match crate::inference::unload_gguf(false) {
        Ok(()) => {
            ui.load_line = Some("Weights unloaded".to_string());
            ui.memory_line = None;
            ui.loading = false;
        }
        Err(error) => {
            let message = match error {
                crate::inference::InferenceExit::Usage(message) => message,
                crate::inference::InferenceExit::Failed => {
                    "Unload failed: weights could not be released".to_string()
                }
            };
            ui.load_line = Some(message.clone());
            output(ui, &message);
        }
    }
}

