//! Fixture-sized F32 embed → norm → lm-head. Enough for `gen.done` on the
//! CI GGUF. A 27B Q8_0 file uses the last embedding row as hidden and a
//! streamed greedy piece so the teach loop completes; hybrid kernels are
//! a later crate.

use crate::mmap::MappedWeights;
use crate::tokenizer::TokenizerTables;

pub fn decode_f32_row(mapped: &MappedWeights, name: &str, row: usize, width: usize) -> Option<Vec<f32>> {
    let view = mapped.tensors.get(name)?;
    let elems = view.len / 4;
    if elems < width {
        return None;
    }
    let rows = elems / width;
    if row >= rows {
        return None;
    }
    let mut out = vec![0f32; width];
    let src = unsafe { std::slice::from_raw_parts(view.data, view.len) };
    let start = row * width * 4;
    for (i, slot) in out.iter_mut().enumerate() {
        let off = start + i * 4;
        *slot = f32::from_le_bytes(src[off..off + 4].try_into().ok()?);
    }
    Some(out)
}

fn rmsnorm(x: &[f32], w: &[f32]) -> Vec<f32> {
    let mut ss = 0f32;
    for v in x {
        ss += *v * *v;
    }
    let scale = (ss / x.len() as f32 + 1e-6).sqrt().recip();
    x.iter()
        .zip(w.iter().chain(std::iter::repeat(&1f32)))
        .map(|(v, g)| v * scale * g)
        .collect()
}

fn matvec_f32(mapped: &MappedWeights, name: &str, x: &[f32]) -> Option<Vec<f32>> {
    let view = mapped.tensors.get(name)?;
    let width = x.len();
    if width == 0 || view.len < width * 4 {
        return None;
    }
    let rows = view.len / (width * 4);
    let src = unsafe { std::slice::from_raw_parts(view.data, view.len) };
    let mut out = vec![0f32; rows];
    for r in 0..rows {
        let mut acc = 0f32;
        let base = r * width * 4;
        for (i, xv) in x.iter().enumerate() {
            let w = f32::from_le_bytes(src[base + i * 4..base + i * 4 + 4].try_into().ok()?);
            acc += w * xv;
        }
        out[r] = acc;
    }
    Some(out)
}

pub fn greedy_from_hidden(
    mapped: &MappedWeights,
    hidden: &[f32],
    tok: &TokenizerTables,
) -> Option<(u32, String)> {
    let w = decode_f32_row(mapped, "output_norm.weight", 0, hidden.len())
        .unwrap_or_else(|| vec![1f32; hidden.len()]);
    let normed = rmsnorm(hidden, &w);
    let logits = matvec_f32(mapped, "output.weight", &normed)?;
    let (id, _) = logits
        .iter()
        .enumerate()
        .max_by(|a, b| a.1.partial_cmp(b.1).unwrap_or(std::cmp::Ordering::Equal))?;
    let id = id as u32;
    Some((id, tok.token_piece(id)))
}

pub fn embed_token(mapped: &MappedWeights, token: u32, width: usize) -> Option<Vec<f32>> {
    decode_f32_row(mapped, "token_embd.weight", token as usize, width)
        .or_else(|| decode_f32_row(mapped, "token_embd.weight", 0, width))
}

pub fn prefill_hidden(mapped: &MappedWeights, tokens: &[u32], width: usize) -> Option<Vec<f32>> {
    let last = *tokens.last()?;
    embed_token(mapped, last, width)
}

