struct BenchTimes {
    mark: std::time::Instant,
    map_ms: u64,
    ctx_ms: u64,
    prompt_ms: u64,
    prefill_ms: u64,
    gen_ms: u64,
    prompt_tokens: u64,
    generated: u32,
}

struct Walk {
    printer: Printer,
    until: Option<String>,
    prompt: Option<String>,
    max_tokens: u32,
    n_ctx: Option<u64>,
    bench: bool,
    compare_ollama: Option<String>,
    times: Option<Mutex<BenchTimes>>,
}

impl Walk {
    fn mark(&self, phase: &str) {
        let Some(times) = &self.times else {
            return;
        };
        let Ok(mut t) = times.lock() else {
            return;
        };
        let now = std::time::Instant::now();
        let dt = now.saturating_duration_since(t.mark).as_millis() as u64;
        t.mark = now;
        match phase {
            "map" => t.map_ms = dt,
            "ctx" => t.ctx_ms = dt,
            "prompt" => t.prompt_ms = dt,
            "prefill" => t.prefill_ms = dt,
            "gen" => t.gen_ms = dt,
            _ => {}
        }
    }
}

