    let ms = started.elapsed().as_millis() as u64;
    let text = value
        .get("response")
        .and_then(Value::as_str)
        .unwrap_or("");
    let tokens = value
        .get("eval_count")
        .and_then(Value::as_u64)
        .unwrap_or(text.split_whitespace().count() as u64) as u32;
    Ok((ms, tokens))
}

