n_tensors, n_kv = struct.unpack("<QQ", f.read(16))
print("ver", ver, "n_tensors", n_tensors, "n_kv", n_kv)

def read_str():
    n = struct.unpack("<Q", f.read(8))[0]
    return f.read(n).decode("utf-8", "replace")

def read_val(typ=None):
    if typ is None:
        typ = struct.unpack("<I", f.read(4))[0]
    if typ == 4:
        return struct.unpack("<I", f.read(4))[0]
    if typ == 5:
        return struct.unpack("<i", f.read(4))[0]
    if typ == 6:
        return struct.unpack("<f", f.read(4))[0]
    if typ == 7:
        return bool(f.read(1)[0])
    if typ == 8:
        return read_str()
    if typ == 10:
        return struct.unpack("<Q", f.read(8))[0]
    if typ == 11:
        return struct.unpack("<q", f.read(8))[0]
    if typ == 0:
        return struct.unpack("<B", f.read(1))[0]
    if typ == 1:
        return struct.unpack("<b", f.read(1))[0]
    if typ == 2:
        return struct.unpack("<H", f.read(2))[0]
    if typ == 3:
        return struct.unpack("<h", f.read(2))[0]
    if typ == 12:
        return struct.unpack("<d", f.read(8))[0]
    if typ == 9:
        et = struct.unpack("<I", f.read(4))[0]
        n = struct.unpack("<Q", f.read(8))[0]
        items = [read_val(et) for _ in range(min(n, 8))]
        # skip rest if truncated display
        if n > 8:
            for _ in range(n-8):
                read_val(et)
        return f"array[{n}] et={et} sample={items[:3]}"
    raise SystemExit(f"bad type {typ}")

kvs = []
for _ in range(n_kv):
    k = read_str()
    v = read_val()
    kvs.append((k, v))
for k,v in kvs:
    if not k.startswith("tokenizer.ggml.tokens") and not k.startswith("tokenizer.ggml.merges") and k != "tokenizer.chat_template":
        print(f"  {k} = {v}")
    elif k == "tokenizer.chat_template":
        s = str(v)
        print(f"  tokenizer.chat_template len={len(s)} head={s[:180]!r}")

names = []
for i in range(n_tensors):
    name = read_str()
    nd = struct.unpack("<I", f.read(4))[0]
    dims = [struct.unpack("<Q", f.read(8))[0] for _ in range(nd)]
    ggml = struct.unpack("<I", f.read(4))[0]
    off = struct.unpack("<Q", f.read(8))[0]
    names.append((name, dims, ggml))

print("--- tensors of interest ---")
for name, dims, ggml in names:
    if name.startswith("blk.0.") or name.startswith("blk.3.") or name.startswith("blk.64.") or name.startswith("mtp.") or name in ("token_embd.weight","output.weight","output_norm.weight"):
        print(f"  {name} dims={dims} type={ggml}")
print("blk prefixes", sorted({n.split('.')[1] for n,_d,_t in names if n.startswith('blk.')})[:20], "... count", len({n.split('.')[1] for n,_d,_t in names if n.startswith('blk.')}))
print("mtp count", sum(1 for n,_,_ in names if n.startswith('mtp.')))
print("nextn count", sum(1 for n,_,_ in names if '.nextn.' in n))
PY

