                width: rows,
                height: 1,
                depth: 1,
            };
            let threads = MtlSize {
                width: THREADS,
                height: 1,
                depth: 1,
            };
            (fns.msg_dispatch)(enc, fns.sel_dispatch, &groups, &threads);
            (fns.msg_void)(enc, fns.sel_end);
            (fns.msg_void)(cmd, fns.sel_commit);
            (fns.msg_void)(cmd, fns.sel_wait);
            let y_ptr = (fns.msg0)(y_buf, fns.sel_contents) as *const f32;
            let mut out = vec![0f32; rows];
            if !y_ptr.is_null() {
                ptr::copy_nonoverlapping(y_ptr, out.as_mut_ptr(), rows);
            }
            (fns.release)(enc);
            (fns.release)(cmd);
            (fns.release)(x_buf);
            (fns.release)(y_buf);
            Some(out)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::generate::matvec;
    use crate::mmap::map_file;
    use crate::parse_path;

    #[test]
    fn metal_q8_matches_cpu_when_available() {
        let dir = std::env::temp_dir().join("psionic-gguf-metal-q8");
        let _ = std::fs::create_dir_all(&dir);
        let path = dir.join("qwen35.gguf");
        crate::format::write_qwen35_hybrid_fixture(&path).unwrap();
        let meta = parse_path(&path).unwrap();
        let mapped = map_file(&path, &meta).unwrap();
        let Some(name) = mapped
            .tensors
            .iter()
            .find(|(_, v)| v.info.ggml_type == 8)
            .map(|(n, _)| n.clone())
        else {
            return;
        };
        let width = mapped.tensors[&name]
            .info
            .dims
            .first()
            .copied()
            .unwrap_or(8) as usize;
        let x = vec![0.25f32; width.max(1)];
        let cpu = matvec(&mapped, &name, &x).unwrap();
        let Ok(metal) = crate::metal_wrap::wrap_shared(&mapped.mmap) else {
            return;
        };
        let _g = bind(Some(&metal));
        let Some(gpu) = try_q8_matvec(&mapped, &name, &x) else {
            return;
        };
        assert_eq!(cpu.len(), gpu.len());
        for (a, b) in cpu.iter().zip(gpu.iter()) {
            assert!(
                (a - b).abs() <= 1e-4 * a.abs().max(1.0),
                "cpu {a} gpu {b} tensor {name}"
            );
        }
    }
}

