            let x_bytes = x.len() * 4;
            let y_bytes = rows * 4;
            let x_buf = (fns.msg_buf)(metal.device, fns.sel_new_buf, x_bytes, STORAGE_SHARED);
            let y_buf = (fns.msg_buf)(metal.device, fns.sel_new_buf, y_bytes, STORAGE_SHARED);
            if x_buf.is_null() || y_buf.is_null() {
                if !x_buf.is_null() {
                    (fns.release)(x_buf);
                }
                if !y_buf.is_null() {
                    (fns.release)(y_buf);
                }
                return None;
            }
            let x_ptr = (fns.msg0)(x_buf, fns.sel_contents) as *mut f32;
            if x_ptr.is_null() {
                (fns.release)(x_buf);
                (fns.release)(y_buf);
                return None;
            }
            ptr::copy_nonoverlapping(x.as_ptr(), x_ptr, x.len());
            let cmd = (fns.msg0)(pipe.queue, fns.sel_cmd);
            let enc = (fns.msg0)(cmd, fns.sel_enc);
            if cmd.is_null() || enc.is_null() {
                (fns.release)(x_buf);
                (fns.release)(y_buf);
                return None;
            }
            (fns.msg1)(enc, fns.sel_set_pipe, pipe.pipeline);
            (fns.msg_set_buf)(enc, fns.sel_set_buf, metal.buffer, 0, 0);
            (fns.msg_set_buf)(enc, fns.sel_set_buf, x_buf, 0, 1);
            (fns.msg_set_buf)(enc, fns.sel_set_buf, y_buf, 0, 2);
            let params = Params {
                rows: rows as u32,
                width: width as u32,
                weight_off: offset as u32,
            };
            (fns.msg_set_bytes)(
                enc,
                fns.sel_set_bytes,
                (&params as *const Params).cast(),
                std::mem::size_of::<Params>(),
                3,
            );
            let groups = MtlSize {
                width: rows,
                height: 1,
                depth: 1,
            };
            let threads = MtlSize {
                width: THREADS,
                height: 1,
                depth: 1,
            };
            (fns.msg_dispatch)(enc, fns.sel_dispatch, &groups, &threads);
            (fns.msg_void)(enc, fns.sel_end);
            (fns.msg_void)(cmd, fns.sel_commit);
            (fns.msg_void)(cmd, fns.sel_wait);
            let y_ptr = (fns.msg0)(y_buf, fns.sel_contents) as *const f32;
            let mut out = vec![0f32; rows];
            if !y_ptr.is_null() {
                ptr::copy_nonoverlapping(y_ptr, out.as_mut_ptr(), rows);
            }
            (fns.release)(enc);
            (fns.release)(cmd);
            (fns.release)(x_buf);
            (fns.release)(y_buf);
            Some(out)
        }
    }
}

