        let Ok(metal) = crate::metal_wrap::wrap_shared(&weights) else {
            return;
        };
        let Some(gpu) = q8_matvec(&metal, 0, rows, width, &x) else {
            return;
        };
        assert_eq!(cpu, gpu, "Metal Q8 matvec must match CPU");
    }
}

