def read_str():
    n = struct.unpack("<Q", f.read(8))[0]
    return f.read(n).decode("utf-8", "replace")

def read_val(typ=None):
    if typ is None:
        typ = struct.unpack("<I", f.read(4))[0]
    if typ == 4:
        return ("u32", struct.unpack("<I", f.read(4))[0])
    if typ == 5:
        return ("i32", struct.unpack("<i", f.read(4))[0])
    if typ == 6:
        return ("f32", struct.unpack("<f", f.read(4))[0])
    if typ == 7:
        return ("bool", struct.unpack("<B", f.read(1))[0])
    if typ == 8:
        return ("str", read_str())
    if typ == 9:
        at = struct.unpack("<I", f.read(4))[0]
        n = struct.unpack("<Q", f.read(8))[0]
        vals = [read_val(at)[1] for _ in range(n)]
        return (f"arr{at}", vals)
    if typ == 10:
        return ("u64", struct.unpack("<Q", f.read(8))[0])
    raise SystemExit(f"bad typ {typ} at {f.tell()}")

