struct Scratch {
    x: *mut c_void,
    y: *mut c_void,
    x_cap: usize,
    y_cap: usize,
}

fn scratch_pair(
    device: *mut c_void,
    x_bytes: usize,
    y_bytes: usize,
) -> Option<(*mut c_void, *mut c_void)> {
    use std::cell::RefCell;
    thread_local! {
        static SCRATCH: RefCell<Scratch> = const {
            RefCell::new(Scratch {
                x: ptr::null_mut(),
                y: ptr::null_mut(),
                x_cap: 0,
                y_cap: 0,
            })
        };
    }
    let fns = fns()?;
    SCRATCH.with(|slot| {
        let mut slot = slot.borrow_mut();
        unsafe {
            if slot.x_cap < x_bytes {
                if !slot.x.is_null() {
                    (fns.release)(slot.x);
                }
                slot.x = (fns.msg_buf)(device, fns.sel_new_buf, x_bytes, STORAGE_SHARED);
                slot.x_cap = if slot.x.is_null() { 0 } else { x_bytes };
            }
            if slot.y_cap < y_bytes {
                if !slot.y.is_null() {
                    (fns.release)(slot.y);
                }
                slot.y = (fns.msg_buf)(device, fns.sel_new_buf, y_bytes, STORAGE_SHARED);
                slot.y_cap = if slot.y.is_null() { 0 } else { y_bytes };
            }
            if slot.x.is_null() || slot.y.is_null() {
                None
            } else {
                Some((slot.x, slot.y))
            }
        }
    })
}

