//! GPU hybrid layer: GDN + FFN on one command buffer, state stays on Metal.
//!
//! Full-attention layers still run on CPU. `--backend cpu` never binds this path.

use crate::format::GgufMeta;
use crate::generate::{Q8_BLOCK, Q8_K};
use crate::metal_gemm;
use crate::metal_wrap::MetalShared;
use crate::mmap::MappedWeights;
use crate::qwen35::DecodeState;

pub struct HybridSpec {
    pub hidden: usize,
    pub epsilon: f32,
    pub state_size: usize,
    pub group_count: usize,
    pub time_step_rank: usize,
    pub inner_size: usize,
    pub conv_kernel: usize,
    pub v_head_reordered: bool,
    pub ffn: usize,
}

pub fn spec_from_meta(meta: &GgufMeta) -> HybridSpec {
    HybridSpec {
        hidden: meta.kv_u64("qwen35.embedding_length").unwrap_or(8) as usize,
        epsilon: meta
            .kv_f32("qwen35.attention.layer_norm_rms_epsilon")
            .unwrap_or(1e-6),
        state_size: meta.kv_u64("qwen35.ssm.state_size").unwrap_or(4) as usize,
        group_count: meta.kv_u64("qwen35.ssm.group_count").unwrap_or(1) as usize,
        time_step_rank: meta.kv_u64("qwen35.ssm.time_step_rank").unwrap_or(1) as usize,
        inner_size: meta.kv_u64("qwen35.ssm.inner_size").unwrap_or(4) as usize,
        conv_kernel: meta.kv_u64("qwen35.ssm.conv_kernel").unwrap_or(4) as usize,
        v_head_reordered: meta
            .kv_u64("qwen35.ssm.v_head_reordered")
            .map(|v| v != 0)
            .unwrap_or(true),
        ffn: meta.kv_u64("qwen35.feed_forward_length").unwrap_or(0) as usize,
    }
}

/// Run every hybrid layer on GPU. Returns None so the CPU graph runs.
pub fn try_forward(
    _mapped: &MappedWeights,
    _meta: &GgufMeta,
    _token: u32,
    _state: &mut DecodeState,
    _hidden: &[f32],
) -> Option<Vec<f32>> {
    None
}

/// One hybrid layer, one wait. Used while the full token graph is unfinished.
pub fn try_hybrid_layer(
    mapped: &MappedWeights,
    spec: &HybridSpec,
    index: usize,
    input: &[f32],
    conv: &mut [f32],
    delta: &mut [f32],
) -> Option<Vec<f32>> {
    if !metal_gemm::bound() {
        return None;
    }
    #[cfg(target_os = "macos")]
    {
        macos::hybrid_layer(mapped, spec, index, input, conv, delta)
    }
    #[cfg(not(target_os = "macos"))]
    {
        let _ = (mapped, spec, index, input, conv, delta);
        None
    }
}

#[cfg(target_os = "macos")]
mod macos {
    use super::*;
    use crate::metal_gemm::{active_metal_ptr, resolve_f32, resolve_q8_pub, Q8Job};
    use std::ffi::c_void;
    use std::ptr;

    pub(super) fn hybrid_layer(
        mapped: &MappedWeights,
        spec: &HybridSpec,
        index: usize,
        input: &[f32],
        conv: &mut [f32],
        delta: &mut [f32],
    ) -> Option<Vec<f32>> {
        let metal = unsafe { &*active_metal_ptr()? };
        if spec.hidden != input.len() || spec.ffn == 0 {
            return None;
        }
        let p = format!("blk.{index}");
        let qkv = resolve_q8_pub(mapped, metal, &format!("{p}.attn_qkv.weight"), spec.hidden)?;
        let z = resolve_q8_pub(mapped, metal, &format!("{p}.attn_gate.weight"), spec.hidden)?;
        let alpha = resolve_q8_pub(mapped, metal, &format!("{p}.ssm_alpha.weight"), spec.hidden)?;
        let beta = resolve_q8_pub(mapped, metal, &format!("{p}.ssm_beta.weight"), spec.hidden)?;
        let ssm_out = resolve_q8_pub(
            mapped,
            metal,
            &format!("{p}.ssm_out.weight"),
            spec.inner_size,
        )?;
        let gate = resolve_q8_pub(mapped, metal, &format!("{p}.ffn_gate.weight"), spec.hidden)?;
        let up = resolve_q8_pub(mapped, metal, &format!("{p}.ffn_up.weight"), spec.hidden)?;
        let down = resolve_q8_pub(mapped, metal, &format!("{p}.ffn_down.weight"), spec.ffn)?;
        let attn_norm = resolve_f32(mapped, metal, &format!("{p}.attn_norm.weight"))?;
        let post = resolve_f32(mapped, metal, &format!("{p}.post_attention_norm.weight"))?;
        let conv_w = resolve_f32(mapped, metal, &format!("{p}.ssm_conv1d.weight"))?;
        let ssm_a = resolve_f32(mapped, metal, &format!("{p}.ssm_a"))
            .or_else(|| resolve_f32(mapped, metal, &format!("{p}.ssm_a.weight")))?;
        let ssm_dt = resolve_f32(mapped, metal, &format!("{p}.ssm_dt.bias"))
            .or_else(|| resolve_f32(mapped, metal, &format!("{p}.ssm_dt")))?;
        let ssm_norm = resolve_f32(mapped, metal, &format!("{p}.ssm_norm.weight"))?;
        crate::metal_gemm::run_hybrid_gpu(
            metal,
            spec,
            &qkv,
            &z,
            &alpha,
            &beta,
            &ssm_out,
            &gate,
            &up,
            &down,
            attn_norm,
            post,
            conv_w,
            ssm_a,
            ssm_dt,
            ssm_norm,
            input,
            conv,
            delta,
        )
    }
}

