        if !slot.pending || slot.hidden.is_null() || slot.hidden_n != n {
            return None;
        }
        drain_queue(slot.device);
        unsafe {
            let p = (fns.msg0)(slot.hidden, fns.sel_contents) as *const f32;
            if p.is_null() {
                slot.pending = false;
                return None;
            }
            let mut out = vec![0f32; n];
            ptr::copy_nonoverlapping(p, out.as_mut_ptr(), n);
            slot.pending = false;
            Some(out)
        }
    })
}

