struct KvResident {
    device: *mut c_void,
    k: *mut c_void,
    v: *mut c_void,
    n_slots: usize,
    n_ctx: usize,
    kv_width: usize,
    bytes: usize,
}

thread_local! {
    static KV: std::cell::RefCell<KvResident> = const {
        std::cell::RefCell::new(KvResident {
            device: ptr::null_mut(),
            k: ptr::null_mut(),
            v: ptr::null_mut(),
            n_slots: 0,
            n_ctx: 0,
            kv_width: 0,
            bytes: 0,
        })
    };
}

pub(super) fn reset_resident() {
    let Some(fns) = fns() else {
        return;
    };
    STREAM.with(|slot| {
        let mut slot = slot.borrow_mut();
        unsafe {
            close_stream(fns, &mut slot);
        }
        slot.pending = false;
    });
    RESIDENT.with(|slot| {
        let slot = slot.borrow();
        unsafe {
            zero_buf(fns, slot.conv, slot.conv_bytes);
            zero_buf(fns, slot.delta, slot.delta_bytes);
        }
    });
    KV.with(|slot| {
        let slot = slot.borrow();
        unsafe {
            zero_buf(fns, slot.k, slot.bytes);
            zero_buf(fns, slot.v, slot.bytes);
        }
    });
    GPU_ATTN.with(|c| c.set(false));
}

fn ensure_kv(
    device: *mut c_void,
    n_slots: usize,
    n_ctx: usize,
    kv_width: usize,
) -> Option<(*mut c_void, *mut c_void)> {
    if n_slots == 0 || n_ctx == 0 || kv_width == 0 {
        return None;
    }
    let fns = fns()?;
    KV.with(|slot| {
        let mut slot = slot.borrow_mut();
        let bytes = n_slots
            .checked_mul(n_ctx)?
            .checked_mul(kv_width)?
            .checked_mul(4)?;
        let reuse = slot.device == device
            && slot.n_slots == n_slots
            && slot.n_ctx == n_ctx
            && slot.kv_width == kv_width
            && !slot.k.is_null()
            && !slot.v.is_null();
        if reuse {
            return Some((slot.k, slot.v));
        }
        unsafe {
            if !slot.k.is_null() {
                (fns.release)(slot.k);
            }
            if !slot.v.is_null() {
                (fns.release)(slot.v);
            }
            slot.k = (fns.msg_buf)(device, fns.sel_new_buf, bytes, STORAGE_SHARED);
            slot.v = (fns.msg_buf)(device, fns.sel_new_buf, bytes, STORAGE_SHARED);
            if slot.k.is_null() || slot.v.is_null() {
                if !slot.k.is_null() {
                    (fns.release)(slot.k);
                }
                if !slot.v.is_null() {
                    (fns.release)(slot.v);
                }
                slot.k = ptr::null_mut();
                slot.v = ptr::null_mut();
                slot.device = ptr::null_mut();
                slot.n_slots = 0;
                slot.bytes = 0;
                return None;
            }
            slot.device = device;
            slot.n_slots = n_slots;
            slot.n_ctx = n_ctx;
            slot.kv_width = kv_width;
            slot.bytes = bytes;
            zero_buf(fns, slot.k, bytes);
            zero_buf(fns, slot.v, bytes);
            Some((slot.k, slot.v))
        }
    })
}

