'
import json,sys
ids=[]
for line in sys.stdin:
    line=line.strip()
    if not line.startswith("{"):
        continue
    try:
        o=json.loads(line)
    except Exception:
        continue
    if o.get("id")=="gen.sample":
        msg=o.get("message","")
        # Sampling token 760 (The)
        parts=msg.split()
        if len(parts)>=3 and parts[1]=="token":
            ids.append(parts[2])
print("IDS", " ".join(ids))
print("N", len(ids))
'

