kernel void q8_matvec(
    device const uchar *weights [[buffer(0)]],
    device const float *x [[buffer(1)]],
    device float *y [[buffer(2)]],
    constant Params &p [[buffer(3)]],
    uint tid [[thread_index_in_threadgroup]],
    uint gid [[threadgroup_position_in_grid]],
    ushort tiisg [[thread_index_in_simdgroup]],
    ushort sgitg [[simdgroup_index_in_threadgroup]])
{
    const uint nr0 = 2u;
    uint r0 = gid * nr0;
    const uint qk = 32u;
    const uint qb = 34u;
    uint blocks = (p.width + qk - 1u) / qk;
    ulong off = ulong(p.off_lo) | (ulong(p.off_hi) << 32u);
    uint row_bytes = blocks * qb;
    uint ix = uint(tiisg) / 4u;
    uint il = uint(tiisg) % 4u;
    uint ib0 = uint(sgitg) * 8u + ix;
    float sum0 = 0.0f;
    float sum1 = 0.0f;
    bool row1 = (r0 + 1u) < p.rows;
    if (r0 < p.rows) {
        for (uint ib = ib0; ib < blocks; ib += 32u) {
            uint xbase = ib * qk + il * 8u;
            float yl[8];
            for (uint i = 0u; i < 8u; i++) {
                uint idx = xbase + i;
                yl[i] = idx < p.width ? x[idx] : 0.0f;
            }
            device const uchar *blk0 = weights + off + r0 * row_bytes + ib * qb;
            float d0 = float(as_type<half>(ushort(uint(blk0[0]) | (uint(blk0[1]) << 8u))));
            float sq0 = 0.0f;
            for (uint i = 0u; i < 8u; i++) {
                sq0 += float(char(blk0[2u + il * 8u + i])) * yl[i];
            }
            sum0 += sq0 * d0;
            if (row1) {
                device const uchar *blk1 = weights + off + (r0 + 1u) * row_bytes + ib * qb;
                float d1 = float(as_type<half>(ushort(uint(blk1[0]) | (uint(blk1[1]) << 8u))));
                float sq1 = 0.0f;
                for (uint i = 0u; i < 8u; i++) {
                    sq1 += float(char(blk1[2u + il * 8u + i])) * yl[i];
                }
                sum1 += sq1 * d1;
            }
        }
    }
    sum0 = simd_sum(sum0);
    sum1 = simd_sum(sum1);
    threadgroup float p0[4];
    threadgroup float p1[4];
    if (tiisg == 0u) {
        p0[sgitg] = sum0;
        p1[sgitg] = sum1;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (tid == 0u && r0 < p.rows) {
        y[r0] = p0[0] + p0[1] + p0[2] + p0[3];
        if (row1) {
            y[r0 + 1u] = p1[0] + p1[1] + p1[2] + p1[3];
        }
    }
}

